import java.util.*;
import java.io.*;
public class JVocabulary2 {
	public static void main(String[] args) throws FileNotFoundException {
		JVocabulary2 v2 = new JVocabulary2();
		ArrayList<String> lst1 = v2.getWords("test1.txt");
		System.out.println("al-kalimat fi list1 = " + lst1);
		ArrayList<String> lst2 = v2.getWords("test2.txt");
		System.out.println("al-kalimat fi list2 = " + lst2);
		v2.compareLists(lst1, lst2);
	}
	//Khutwa 1: Arraf al-method allati tuqarin qaimatayn li-ijad al-akbar
	public void compareLists(ArrayList<String> list1, ArrayList<String> list2 ) {
		if ( list1.size() > list2.size() ) {
			System.out.println("list1 fiha kalimat akthar.");
		} else if ( list2.size() > list1.size() ) {
			System.out.println("list2 fiha kalimat akthar");
		} else {
			System.out.println("list1 wa list2 ladayhuma nafs 'adad al-kalimat.");
		}
	}
	//Khutwa 2: Arraf al-method allati tanshii qaimat kalimat min malaf
	public ArrayList<String> getWords(String fileName) {
		//Khutwa 2.1: Inshe qaimah farigha li-takhzin al-kalimat
		ArrayList<String> words = new ArrayList<String>();
		//Khutwa 2.2: Hawit al-kod alladhi qad yurmee istithna fi blok try
		try {
			//Khutwa 2.2.1: Rabit BufferedReader hawla FileReader
			FileReader fr = new FileReader(fileName); 
			BufferedReader br = new BufferedReader(fr); 
			//Khutwa 2.2.2: Istakhdim BufferedReader li-qira'at khat wahid fi al-waqt
			String line = null;
			while ( ( line = br.readLine() ) != null) {
				//Afsa al-satr ila kalimat, mutajahil halat al-huruf
				String[] tokens = line.toLowerCase().split(" ");
				//Adif kulla kalima fi al-satr ila al-qaimah
				for (String token : tokens) {
					words.add(token);
				}
			}
			//Khutwa 2.2.3: Sakkir BufferedReader al-murtabit bil-malaf
			br.close();
		//Khutwa 2.3: Ta'amal ma'a jami3 al-istithna'at al-mumkin an tusqut fi blok try
		} catch (FileNotFoundException ex) {
			System.out.println("al-malaf lam yujad");
		} catch (IOException ex ) {
			System.out.println("mushkila fi al-malaf!");
		}
		//Khutwa 2.4: a3id al-qaimah
		return words;
	}
}
